import { Request, Response, Router } from 'express';
import { AdvanceOrderUseCase } from '../../application/use-cases/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../../application/use-cases/CancelOrderUseCase';
import { GetOrderUseCase } from '../../application/use-cases/GetOrderUseCase';
import { ListOrdersByStateUseCase } from '../../application/use-cases/ListOrdersByStateUseCase';
import { PlaceOrderUseCase } from '../../application/use-cases/PlaceOrderUseCase';
import { parsePlaceOrderBody, parseStatusBody, requireString } from './requestParsing';

export interface OrderUseCases {
  placeOrder: PlaceOrderUseCase;
  getOrder: GetOrderUseCase;
  listOrdersByState: ListOrdersByStateUseCase;
  advanceOrder: AdvanceOrderUseCase;
  cancelOrder: CancelOrderUseCase;
}

export class OrderController {
  constructor(private readonly useCases: OrderUseCases) {}

  routes(): Router {
    const router = Router();
    router.post('/', this.place);
    router.get('/', this.listByState);
    router.get('/:id', this.get);
    router.patch('/:id/status', this.advance);
    router.post('/:id/cancel', this.cancel);
    return router;
  }

  private readonly place = (req: Request, res: Response): void => {
    res.status(201).json(this.useCases.placeOrder.execute(parsePlaceOrderBody(req.body)));
  };

  private readonly listByState = (req: Request, res: Response): void => {
    const state = requireString(req.query.state, 'state (query parameter)');
    res.json(this.useCases.listOrdersByState.execute(state));
  };

  private readonly get = (req: Request, res: Response): void => {
    res.json(this.useCases.getOrder.execute(String(req.params.id)));
  };

  private readonly advance = (req: Request, res: Response): void => {
    res.json(this.useCases.advanceOrder.execute(String(req.params.id), parseStatusBody(req.body)));
  };

  private readonly cancel = (req: Request, res: Response): void => {
    res.json(this.useCases.cancelOrder.execute(String(req.params.id)));
  };
}

